// dogemap-mondrian/1 vectors. Hand-derived from the packer rules
// (docs/extensions/block-mondrian.md), not generated by the code under test.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { koinuFromDoge, mondrianLayout, mondrianSvg, renderBlockSvg, txSquareSize } from './dogemap-mondrian.mjs';

test('square size: ceil(log10(koinu)) - 5, at least 1, exact at powers of ten', () => {
  const cases = [
    [0, 1],
    [1, 1],
    [100000, 1],
    [100001, 1],
    [1000000, 1],
    [1000001, 2],
    [100000000, 3], // 1 DOGE
    [100000001, 4],
    [5000000000, 5], // 50 DOGE
    ['1000000000000', 7], // 10,000 DOGE coinbase
    [10n ** 18n, 13],
    [10n ** 18n + 1n, 14],
  ];
  for (const [k, want] of cases) assert.equal(txSquareSize(k), want, `koinu ${k}`);
  assert.equal(koinuFromDoge('10000.00000000'), 1000000000000n);
  assert.equal(koinuFromDoge('0.1'), 10000000n);
  assert.throws(() => txSquareSize(-1));
  assert.throws(() => txSquareSize(1.5));
});

test('one transaction fills the picture', () => {
  const l = mondrianLayout(['1000000000000']);
  assert.deepEqual({ w: l.width, cw: l.contentW, ch: l.contentH, s: l.squares }, { w: 7, cw: 7, ch: 7, s: [{ x: 0, y: 0, r: 7 }] });
  assert.equal(
    renderBlockSvg(['1000000000000']),
    '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 26 26" width="576" height="576" shape-rendering="crispEdges">' +
      '<rect width="26" height="26" fill="#000000"/><g fill="#C2A633"><rect x="0" y="0" width="26" height="26"/></g></svg>',
  );
});

test('sizes [5, 3]: width 6, the 3 starts a new row under the 5, centered', () => {
  const l = mondrianLayout([5000000000, 100000000]);
  assert.equal(l.width, 6);
  assert.deepEqual(l.squares, [
    { x: 0, y: 0, r: 5 },
    { x: 0, y: 5, r: 3 },
  ]);
  assert.equal(l.contentW, 5);
  assert.equal(l.contentH, 8);
  assert.equal(
    mondrianSvg(l),
    '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 30 30" width="576" height="576" shape-rendering="crispEdges">' +
      '<rect width="30" height="30" fill="#000000"/><g fill="#C2A633">' +
      '<rect x="6" y="0" width="18" height="18"/><rect x="6" y="20" width="10" height="10"/></g></svg>',
  );
});

test('sizes [3, 1, 1, 1]: the small ones stack in the column beside the 3', () => {
  const l = mondrianLayout([100000000, 50000, 100000, 1000000]);
  assert.equal(l.width, 4);
  assert.deepEqual(l.squares, [
    { x: 0, y: 0, r: 3 },
    { x: 3, y: 0, r: 1 },
    { x: 3, y: 1, r: 1 },
    { x: 3, y: 2, r: 1 },
  ]);
  assert.equal(
    mondrianSvg(l, { size: 288, colors: { background: '#111111' } }),
    '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 14 14" width="288" height="288" shape-rendering="crispEdges">' +
      '<rect width="14" height="14" fill="#111111"/><g fill="#C2A633">' +
      '<rect x="0" y="0" width="10" height="10"/><rect x="12" y="0" width="2" height="2"/>' +
      '<rect x="12" y="4" width="2" height="2"/><rect x="12" y="8" width="2" height="2"/></g></svg>',
  );
});

test('deterministic and inside the grid width', () => {
  const vals = [];
  let x = 987654321n;
  for (let i = 0; i < 400; i += 1) {
    x = (x * 6364136223846793005n + 1442695040888963407n) % (1n << 64n);
    vals.push((x % 10n ** BigInt(4 + Number(x % 9n))).toString());
  }
  const a = mondrianLayout(vals);
  assert.deepEqual(mondrianLayout(vals), a);
  assert.equal(a.squares.length, vals.length);
  for (const q of a.squares) assert.ok(q.x >= 0 && q.y >= 0 && q.x + q.r <= a.width, 'inside the grid width');
});
